import{_ as t,c as s,o as r,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const m=JSON.parse('{"title":"《周易集注》简介","description":"周易集注 - 《周易集注》简介","frontmatter":{"title":"《周易集注》简介","description":"周易集注 - 《周易集注》简介"},"headers":[],"relativePath":"zh/classics/jizhu/001.md","filePath":"zh/classics/jizhu/001.md"}'),n={name:"zh/classics/jizhu/001.md"};function i(c,a,o,d,p,h){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《周易集注》简介",tabindex:"-1"},[l("《周易集注》简介 "),e("a",{class:"header-anchor",href:"#《周易集注》简介","aria-label":"Permalink to “《周易集注》简介”"},"​")],-1),e("p",null,"《周易集注》是明代学者来知德所著的一部易学著作。该书共16卷，继承并发展了朱熹的理数之学，对《周易》的象数进行了深入研究和阐释。来知德在书中侧重于取《系辞》中的“错综其数”来论象，以象数来阐释义理，再以义理来印证象数，纵横推演，为学易者提供了深入理解《周易》的新视角。",-1),e("p",null,"来知德（1525—1604），字矣鲜，别号瞿唐，是明代著名的理学家和易学家。他的《周易集注》用功尤深，成为易学研究的重要著作，亦称来氏易学。郑同，作为易学学者和北京学易斋的创办人，对《周易集注》进行了整理。",-1),e("p",null,"《周易集注》在明清两代流传甚广，对后世的易学研究产生了深远的影响。书中的注解先释象义、字义及错综义，然后训本卦本爻正意，参互旁通，自成一说。通过该书，读者可以对《周易》所用的“错”“综”等阐释方法有更深入的理解。",-1),e("p",null,"此外，来知德在《周易集注》中对《周易》中的卦象、爻辞和象文进行了详细的分析，阐述了其中的哲学思想和世界观。这部作品不仅体现了作者深厚的易学功底，也为后来的易学研究提供了宝贵的参考和启示。",-1)])])}const _=t(n,[["render",i]]);export{m as __pageData,_ as default};
